CREATE INDEX idx_user_plans_stripe_customer_id ON public.user_plans USING btree (stripe_customer_id);
CREATE INDEX idx_user_plans_stripe_subscription_id ON public.user_plans USING btree (stripe_subscription_id);
CREATE INDEX idx_user_plans_user_id ON public.user_plans USING btree (user_id);
CREATE INDEX idx_user_usage_last_reset ON public.user_usage USING btree (last_reset);
CREATE INDEX idx_user_usage_user_id ON public.user_usage USING btree (user_id);
CREATE INDEX idx_payment_history_created_at ON public.payment_history USING btree (created_at DESC);
CREATE INDEX idx_payment_history_event_id ON public.payment_history USING btree (event_id);
CREATE INDEX idx_payment_history_stripe_subscription_id ON public.payment_history USING btree (stripe_subscription_id);
CREATE INDEX idx_payment_history_user_id ON public.payment_history USING btree (user_id);
CREATE INDEX job_applications_user_id_idx ON public.job_applications USING btree (user_id);
CREATE INDEX resume_versions_user_id_idx ON public.resume_versions USING btree (user_id);
CREATE TRIGGER update_user_plans_updated_at BEFORE UPDATE ON public.user_plans FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();
CREATE TRIGGER update_user_usage_updated_at BEFORE UPDATE ON public.user_usage FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();
CREATE TRIGGER job_applications_updated_at BEFORE UPDATE ON public.job_applications FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TRIGGER resume_versions_updated_at BEFORE UPDATE ON public.resume_versions FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TRIGGER on_auth_user_created AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION handle_new_user();
